import sys
import os
import multiprocessing as mp


def make_tree(depth):
    if depth > 0:
        child_depth = depth - 1
        return make_tree(child_depth), make_tree(child_depth)
    return (depth,)


def build_tree_group(task):
    depth, tree_count = task
    build = make_tree
    for _ in range(tree_count):
        build(depth)

    nodes_per_tree = (1 << (depth + 1)) - 1
    return tree_count, depth, tree_count * nodes_per_tree


def available_cpus():
    try:
        return len(os.sched_getaffinity(0))
    except (AttributeError, OSError):
        return os.cpu_count() or 1


def main():
    n = int(sys.argv[1])

    stretch_depth = n + 1
    make_tree(stretch_depth)
    stretch_check = (1 << (stretch_depth + 1)) - 1

    tasks = [
        (depth, 1 << (n - depth + 4))
        for depth in range(4, n + 1, 2)
    ]

    worker_count = min(len(tasks), available_cpus()) if tasks else 0

    if worker_count > 1:
        with mp.Pool(worker_count) as pool:
            long_lived_tree = make_tree(n)
            results = pool.map(build_tree_group, tasks)
    else:
        long_lived_tree = make_tree(n)
        results = [build_tree_group(task) for task in tasks]

    long_lived_check = (1 << (n + 1)) - 1

    lines = [
        f"stretch tree of depth {stretch_depth}\t check: {stretch_check}"
    ]
    lines.extend(
        f"{tree_count}\t trees of depth {depth}\t check: {checksum}"
        for tree_count, depth, checksum in results
    )
    lines.append(
        f"long lived tree of depth {n}\t check: {long_lived_check}"
    )

    print("\n".join(lines))

    # Keep the tree alive until after all output values have been prepared.
    del long_lived_tree


if __name__ == "__main__":
    main()
