import sys
import math


ITERATIONS = 10


def run_python(n):
    def multiply_a(vector):
        result = [0.0] * n
        for i in range(n):
            denominator = (i * (i + 3)) // 2 + 1
            increment = i + 1
            total = 0.0
            for value in vector:
                total += value / denominator
                denominator += increment
                increment += 1
            result[i] = total
        return result

    def multiply_at(vector):
        result = [0.0] * n
        for i in range(n):
            denominator = (i * (i + 1)) // 2 + 1
            increment = i + 2
            total = 0.0
            for value in vector:
                total += value / denominator
                denominator += increment
                increment += 1
            result[i] = total
        return result

    def multiply_ata(vector):
        return multiply_at(multiply_a(vector))

    u = [1.0] * n
    v = None

    for _ in range(ITERATIONS):
        v = multiply_ata(u)
        u = multiply_ata(v)

    numerator = sum(x * y for x, y in zip(u, v))
    denominator = sum(x * x for x in v)
    return math.sqrt(numerator / denominator)


def run_numpy(n, np):
    columns = np.arange(n, dtype=np.float64)[None, :]
    block_size = max(1, min(n, 1_000_000 // n))

    def multiply(vector, transpose):
        result = np.empty(n, dtype=np.float64)

        for start in range(0, n, block_size):
            end = min(start + block_size, n)
            rows = np.arange(start, end, dtype=np.float64)[:, None]

            sums = rows + columns
            matrix = sums.copy()
            matrix += 1.0
            matrix *= sums
            matrix *= 0.5
            matrix += columns if transpose else rows
            matrix += 1.0
            np.reciprocal(matrix, out=matrix)

            result[start:end] = matrix.dot(vector)

        return result

    def multiply_ata(vector):
        return multiply(multiply(vector, False), True)

    u = np.ones(n, dtype=np.float64)
    v = None

    for _ in range(ITERATIONS):
        v = multiply_ata(u)
        u = multiply_ata(v)

    return math.sqrt(float(np.dot(u, v) / np.dot(v, v)))


def main():
    n = int(sys.argv[1])

    try:
        import numpy as np
    except ImportError:
        estimate = run_python(n)
    else:
        estimate = run_numpy(n, np) if n >= 128 else run_python(n)

    print(f"{estimate:.9f}")


if __name__ == "__main__":
    main()
